        const typing = ae && (ae.tagName === 'INPUT' || ae.tagName === 'TEXTAREA' || ae.tagName === 'SELECT') && ac && ac.contains(ae);
        if (_npCase.step === 1 && ac && !typing) npCaseRender(ac);
