/** 本机抽帧差分：小画布 64×64 灰度，比相邻帧平均差；阈值＝max(24, 中位数+2.5×MAD 折算σ)——中位数抗噪，短片子/单切换点不会被自己顶出阈值；两点至少隔 1.2 秒
 *  素材库用 opts：step 更密、阈值更敏、只留局部峰值，当「建议切点」用（不改默认行为） */
function npcDiffMarks(m, opts) {
  const op = opts || {};
  const optStep = Number(op.step) || 0;
  const optGap = Number(op.minGap) || 0;
  const optMax = Number(op.maxMarks) || 0;
  const peak = !!op.peak;
  return new Promise((resolve, reject) => {
    const v = document.createElement('video');
    v.muted = true; v.playsInline = true; v.preload = 'auto';
    v.style.cssText = 'position:fixed;left:-9999px;top:0;width:2px;height:2px;opacity:0;pointer-events:none;';
    document.body.appendChild(v);
    let done = false;
    const fin = (fn, x) => {
      if (done) return; done = true; clearTimeout(tm);
      try { v.removeAttribute('src'); v.load(); } catch (_) {}
      try { v.remove(); } catch (_) {}
      fn(x);
    };
    const tm = setTimeout(() => fin(reject, new Error('扫分镜超时')), 90000);
    v.onerror = () => fin(reject, new Error('这台浏览器播不动这个格式'));
    v.onloadeddata = async () => {
      try {
        const dur = Number(v.duration) || 0;
        const vw = v.videoWidth || 0, vh = v.videoHeight || 0;
        if (!dur || !vw || !vh) { fin(reject, new Error('读不出画面')); return; }
        const S = 64;
        const cv = document.createElement('canvas'); cv.width = S; cv.height = S;
        const ctx = cv.getContext('2d', { willReadFrequently: true });
        const step = optStep > 0 ? Math.max(optStep, dur / 900) : Math.max(0.6, dur / 300);
        let prev = null;
        const diffs = [], at = [];
        for (let t = 0; t < dur - 0.12; t += step) {
          if (done) return;
          const wev = npcWaitEvent(v, 'seeked', 2500);
          try { v.currentTime = t; } catch (_) { continue; }
          try { await wev; } catch (_) { continue; }
          let px = null;
          try { ctx.drawImage(v, 0, 0, S, S); px = ctx.getImageData(0, 0, S, S).data; } catch (_) {}
          if (!px) continue;
          const cur = new Uint8Array(S * S);
          for (let i = 0, p = 0; i < cur.length; i++, p += 4) cur[i] = (px[p] * 0.299 + px[p + 1] * 0.587 + px[p + 2] * 0.114) | 0;
          if (prev) {
            let s = 0;
            for (let i = 0; i < cur.length; i++) s += Math.abs(cur[i] - prev[i]);
            diffs.push(s / cur.length); at.push(t);
          }
          prev = cur;
        }
        if (diffs.length < 2) { fin(resolve, []); return; }
        const sorted = diffs.slice().sort((a, b) => a - b);
        const mid = sorted.length >> 1;
        const med = sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
        const absdev = diffs.map(d => Math.abs(d - med)).sort((a, b) => a - b);
        const mad = absdev.length % 2 ? absdev[mid] : (absdev[mid - 1] + absdev[mid]) / 2;
        const thr = peak ? Math.max(14, med + 1.8 * 1.4826 * mad) : Math.max(24, med + 2.5 * 1.4826 * mad);
        const marks = [];
        const minGap = optGap > 0 ? optGap : 1.2;
        if (peak) {
          const cands = [];
          diffs.forEach((d, i) => {
            if (d < thr) return;
            const l = i > 0 ? diffs[i - 1] : -1, r = i < diffs.length - 1 ? diffs[i + 1] : -1;
            if (d < l || d < r) return;
            cands.push({ t: at[i], d: d });
          });
          cands.sort((a, b) => b.d - a.d).forEach(c => {
            if (marks.some(t => Math.abs(t - c.t) < minGap)) return;
            marks.push(c.t);
          });
          marks.sort((a, b) => a - b);
        } else {
          let last = -9;
          diffs.forEach((d, i) => {
            if (d < thr) return;
            const t = at[i];
            if (t - last < minGap) return;
            marks.push(t); last = t;
          });
        }
        fin(resolve, marks.map(t => Math.round(t * 10) / 10).slice(0, optMax > 0 ? optMax : 300));
      } catch (e) { fin(reject, e); }
    };
    try { v.src = m.url; } catch (e) { fin(reject, e); }
  });
}
