    const stages = st.map(s => ({ name: String((s && s.name) || '').slice(0, 16), kb: (Array.isArray(s && s.kb) ? s.kb : []).map(String).slice(0, 6) })).filter(s => s.name).slice(0, sp[1]);
    if (stages.length < 2) throw new Error('AI 没蒸出可用的环节轴');
