/** 这一张从哪儿拍：按画面里的场子分桌边／地面／门口／人物，别六张一个角度 */
function npShotCameraLine(w, it, i) {
  const st = npShotStyle(npLookOf(w));
  if (!st.camera) return '';
  const blob = String((it && it.topic) || '') + ' ' + npBriefVisual(it) + ' ' + npBriefBg(it, st);
  if (st.tag === '广告片') {
    if (/蹲|地上|地面|铺砖现场|墙角/.test(blob)) return '【机位】略低机位，贴地拍，主体占下半，背景压暗。';
    if (/桌|台面|报价单|料单|单子|本子|屏幕|键盘/.test(blob)) return '【机位】45 度俯拍，台面占下半，主体摆正中。';
    if (/门口|楼道|门框|单元/.test(blob)) return '【机位】三脚架平视，主体居中，背景干净有层次。';
    const ads = ['三脚架平视，主体居中，背景干净有层次', '45 度侧俯，主体占画面下半，背景压暗',
      '略低机位，主体显得挺拔，背景干净', '近景特写，主体占画面三分之二，背景虚化'];
    return '【机位】' + ads[i % ads.length] + '。';
  }
  if (st.tag !== '手机随拍') return '';
  if (/蹲|地上|地面|铺砖现场|墙角/.test(blob)) {
    return '【机位】手机在膝盖高，蹲下来离一米左右拍，竖拍，前景带一点杂物。';
  }
  if (/桌|台面|报价单|料单|单子|本子|屏幕|键盘/.test(blob)) {
    return '【机位】手机在桌边' + (i % 2 ? '斜上方 45 度' : '俯拍') + '，离桌面四五十厘米，竖拍，桌面占大半，手从画面边上伸进来。';
  }
  if (/门口|楼道|门框|单元/.test(blob)) {
    return '【机位】手机在门口离两米左右往里拍，竖拍，画面带一点门框或门口杂物。';
  }
  const ppl = ['手机在侧后方，齐胸口高，离一米半，竖拍，人物偏在画面一边，不摆姿势',
    '手机举到眼睛高，隔着半步拍，人物侧身、没看镜头',
    '手机在侧前方略低，离一米左右，拍到半身和手上的动作'];
  return '【机位】' + ppl[i % ppl.length] + '。';
}
