      id: String((x && x.id) || npShotId()),
      text: String((x && x.text) || ''),
      keySid: String((x && x.keySid) || ''),           // 这一屏那句话＝哪一行（六十四改③；没点过就是这一屏头一句）
      keyText: '',                                     // 派生物：keySid 对应的那句字，npSegSync 里现算
      form: NP_SHOT_FORMS.indexOf(form) >= 0 ? form : '',
