  const l = lipPeel(r.job);
  await lipPatch(d.arId, l);
  d.mode = 'view'; d.job = l;
  if (document.getElementById('dirModal').classList.contains('open')) npLipPaint();
  const ac = document.getElementById('noteArchiveContent');
  if (ac && typeof renderNoteArchive === 'function') { try { renderNoteArchive(ac); } catch (_) {} }
