    await lipPatch(arId, { state: 'canceled' });
    if (typeof toast === 'function') toast('这张单撤了——稿子还在档案里，想重交再点一次那颗出口钮');
    if (_lipD && _lipD.arId === String(arId)) { _lipD.job = Object.assign({}, l, { state: 'canceled', canCancel: false }); npLipPaint(); }
    const ac = document.getElementById('noteArchiveContent');
    if (ac && typeof renderNoteArchive === 'function') { try { renderNoteArchive(ac); } catch (_) {} }
