    let done = false;
    const tm = setTimeout(() => { if (done) return; done = true; v.removeEventListener('loadeddata', h); rej(new Error('这条片还没读好')); }, 8000);
    const h = () => { if (done) return; done = true; clearTimeout(tm); v.removeEventListener('loadeddata', h); res(); };
    v.addEventListener('loadeddata', h);
