  if (!g) return;
  c.frame = g; c.t = g.t;
  npFacadePaint(container);
  if (typeof toast === 'function') toast('用了 ' + g.t.toFixed(1) + ' 秒这一帧——右边挑版式、写标题，再点「✓ 定这张当封面」');
