  const usedName = String(c.usedByName || '另一条笔记');
  const own = Array.isArray(c.tags) ? c.tags.slice() : [];
  const inhRaw = Array.isArray(v.tags) ? v.tags.filter(Boolean) : [];
  const noInh = Array.isArray(c.noInherit) ? c.noInherit : [];
